class Solution:
    def findLUSlength(self, strs: list[str]) -> int:
        def contained(a, b):
            i = 0
            for char in b:
                if i < len(a) and a[i] == char:
                    i += 1
            return i == len(a)
        best = -1
        for i, word in enumerate(strs):
            if all(i == j or not contained(word, other) for j, other in enumerate(strs)):
                best = max(best, len(word))
        return best
